import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Select from 'flarum/common/components/Select';
import { HEIGHT_PRESETS } from '../../common/heroStyle';
const t = (key, params = {}) => app.translator.trans(`walsgit-custom-heroes.admin.height.${key}`, params, true);

/** Bounds of custom heights, as validated by the server. */
const BOUNDS = {
  desktop: 800,
  tablet: 800,
  mobile: 600
};
const MIN = 80;
export default class HeightForm extends Component {
  view() {
    const {
      value,
      onchange
    } = this.attrs;
    const preset = size => t(`preset_${size}`, HEIGHT_PRESETS[size]);
    return m("div", {
      className: "wch-HeightForm"
    }, m("div", {
      className: "Form-group"
    }, m("label", null, t('preset_label')), m(Select, {
      value: value.preset,
      options: {
        auto: t('preset_auto'),
        s: preset('s'),
        m: preset('m'),
        l: preset('l'),
        custom: t('preset_custom')
      },
      onchange: choice => onchange(choice === 'custom' ? {
        preset: 'custom',
        ...HEIGHT_PRESETS.m
      } : {
        preset: choice
      })
    }), m("p", {
      className: "helpText"
    }, t('preset_help'))), value.preset === 'custom' && m("div", {
      className: "Form-group wch-HeightForm-custom"
    }, ['desktop', 'tablet', 'mobile'].map(breakpoint => m("label", null, m("span", null, t(`${breakpoint}_label`)), m("span", {
      className: "wch-HeightForm-input"
    }, m("input", {
      className: "FormControl",
      type: "number",
      min: MIN,
      max: BOUNDS[breakpoint],
      value: value[breakpoint],
      onchange: e => {
        const px = parseInt(e.target.value, 10) || MIN;
        onchange({
          ...value,
          [breakpoint]: Math.min(BOUNDS[breakpoint], Math.max(MIN, px))
        });
      }
    }), m("span", null, "px"))))));
  }
}
flarum.reg.add('walsgit-custom-heroes', 'admin/components/HeightForm', HeightForm);